mkdir -p /tmp/srcset-scratch && cat > /tmp/srcset-scratch/ScratchTest.java <<'EOF'
package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class ScratchTest {
    @Test void edges() {
        Safelist safelist = Safelist.relaxed().addAttributes("img", "srcset");
        // empty srcset removed
        assertEquals("<img>", Jsoup.clean("<img srcset=''>", safelist));
        // whitespace-only
        assertEquals("<img>", Jsoup.clean("<img srcset='  , , '>", safelist));
        // source tag, generic handling (no protocols configured for source -> any URL ok)
        Safelist s2 = Safelist.none().addTags("source").addAttributes("source", "srcset");
        assertEquals("<source srcset=\"any://ok 1x\">", Jsoup.clean("<source srcset='any://ok 1x'>", s2));
        // multiple spaces normalized, reparse-stable
        String once = Jsoup.clean("<img srcset='https://e.com/a.png   1x'>", safelist);
        assertEquals("<img srcset=\"https://e.com/a.png 1x\">", once);
        assertEquals(once, Jsoup.clean(once, safelist));
        // url containing comma kept as one candidate
        assertEquals("<img srcset=\"https://e.com/a,b.png 1x\">",
            Jsoup.clean("<img srcset='https://e.com/a,b.png 1x'>", safelist));
        // entity-decoded comma inside URL
        assertEquals("<img srcset=\"https://e.com/a,b.png 1x\">",
            Jsoup.clean("<img srcset='https://e.com/a&comma;b.png 1x'>", safelist));
        // parens descriptor invalid
        assertEquals("<img>", Jsoup.clean("<img srcset='https://e.com/a.png (100w)'>", safelist));
        // tab/newline separators
        assertEquals("<img srcset=\"https://e.com/a.png 1x, https://e.com/b.png 2x\">",
            Jsoup.clean("<img srcset='https://e.com/a.png\t1x,\nhttps://e.com/b.png  2x'>", safelist));
        // isValidBodyHtml path does not throw
        assertTrue(Jsoup.isValid("<img srcset='https://e.com/a.png 1x'>", safelist));
        assertFalse(Jsoup.isValid("<img srcset='javascript:x 1x'>", safelist));
        // direct isSafeAttribute call: allowed name -> true (candidates validated at clean time)
        Document doc = Jsoup.parse("<img srcset='javascript:x 1x'>");
        org.jsoup.nodes.Element img = doc.selectFirst("img");
        assertTrue(safelist.isSafeAttribute("img", img, img.attributes().iterator().next()));
        // removeAttributes still works
        assertEquals("<img>", Jsoup.clean("<img srcset='https://e.com/a.png 1x'>",
            safelist.removeAttributes("img", "srcset")));
    }
